const updateCompetitor = `-- name: UpdateCompetitor :one
UPDATE competitors SET website = $1, status = $2
WHERE id = $3 AND workspace_id = $4
RETURNING id, workspace_id, name, website, status, summary, summary_at, created_at
`

type UpdateCompetitorParams struct {
	Website     string `json:"website"`
	Status      string `json:"status"`
	ID          string `json:"id"`
	WorkspaceID string `json:"workspace_id"`
}

func (q *Queries) UpdateCompetitor(ctx context.Context, arg UpdateCompetitorParams) (Competitor, error) {
	row := q.db.QueryRow(ctx, updateCompetitor,
		arg.Website,
		arg.Status,
		arg.ID,
		arg.WorkspaceID,
	)
	var i Competitor
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.Website,
		&i.Status,
		&i.Summary,
		&i.SummaryAt,
		&i.CreatedAt,
	)
	return i, err
}
